-- One native monetary/source snapshot for interactive reports and the
-- retained statement workflow. INVOKER only;tenant RLS stays authoritative.
CREATE FUNCTION public.counterparty_statement_rows(uuid,date,date,jsonb,date,uuid,text,integer,integer,uuid[])
RETURNS TABLE("snapshotAt" text,"sourceCount" integer,denied integer,unknown integer,"billCount" integer,"currencyCount" integer,"dayCount" integer,"entryCount" integer,"validRange" boolean,currencies jsonb,entries jsonb,days jsonb,"sourceFingerprint" text,"sourceScope" jsonb)
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog SET DateStyle='ISO,YMD' SET TimeZone='UTC' AS $native$
#variable_conflict use_column
BEGIN
 IF nullif(current_setting('app.academy_id',true),'') IS NULL OR $1 IS NULL OR $2 IS NULL OR $3 IS NULL OR $2 NOT BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' OR $3 NOT BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' OR $2>$3
  OR jsonb_typeof($4) IS DISTINCT FROM 'object' OR octet_length($4::text)>1048576 OR $9 IS NULL OR $9 NOT BETWEEN 1 AND 2001
  OR num_nonnulls($5,$6,$7,$8) NOT IN(0,4) OR($5 IS NOT NULL AND $5 NOT BETWEEN DATE '1900-01-01' AND DATE '9999-12-31') OR($7 IS NOT NULL AND $7 NOT IN('manual_balance','custody','payable')) OR($8 IS NOT NULL AND $8 NOT BETWEEN 0 AND 200)
  OR($10 IS NOT NULL AND(cardinality($10) NOT BETWEEN 1 AND 200 OR array_ndims($10) IS DISTINCT FROM 1 OR array_position($10,NULL::uuid) IS NOT NULL OR cardinality($10)<>(SELECT count(DISTINCT id) FROM unnest($10) id)))
 THEN RAISE EXCEPTION 'COUNTERPARTY_STATEMENT_SOURCE_INPUT_INVALID' USING ERRCODE='22023';END IF;
 RETURN QUERY
WITH party AS MATERIALIZED(SELECT * FROM public.financial_payees WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND id=$1),
 party_access AS(SELECT EXISTS(SELECT 1 FROM party p WHERE p.kind<>'academy' AND NOT EXISTS(SELECT 1 FROM(VALUES('payees.view'),('counterparty-balances.view'),('financial-reports.view')) cap(name) WHERE public.approval_scope_nonempty($4::jsonb->cap.name) IS NOT TRUE OR(p.hub_id IS NOT NULL AND public.scope_contains($4::jsonb->cap.name,jsonb_build_object('all',false,'hubs',jsonb_build_array(p.hub_id))) IS NOT TRUE))) allowed),
 bills AS MATERIALIZED(SELECT b.*,public.expense_reminder_bill_allows(b.id,$4::jsonb) AND NOT EXISTS(SELECT 1 FROM(SELECT l.hub_id FROM public.expense_bill_lines l WHERE l.academy_id=b.academy_id AND l.bill_id=b.id UNION SELECT a.hub_id FROM public.expense_payments p JOIN public.finance_accounts a ON a.academy_id=p.academy_id AND a.id=p.funding_account WHERE p.academy_id=b.academy_id AND p.bill_id=b.id) contexts CROSS JOIN(VALUES ('counterparty-balances.view'),('financial-reports.view')) cap(name) WHERE public.scope_contains($4::jsonb->cap.name,jsonb_build_object('all',contexts.hub_id IS NULL,'hubs',CASE WHEN contexts.hub_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(contexts.hub_id) END)) IS NOT TRUE) allowed FROM public.expense_bills b WHERE b.academy_id=(SELECT academy_id FROM party) AND b.payee_id=$1 AND b.posted_on<=$3::date AND $3::date-$2::date<=3660 AND($10::uuid[] IS NULL OR b.currency_id=ANY($10)) LIMIT 10001),
 raw AS MATERIALIZED(
 SELECT e.academy_id,e.journal_id,e.line_number,e.posted_on,e.currency_id,e.unit_scale,e.delta_minor,'manual_balance'::text family,e.category,j.reverses_id correction_of,NOT EXISTS(SELECT 1 FROM(SELECT DISTINCT a.hub_id FROM public.finance_journal_lines l JOIN public.finance_accounts a ON a.academy_id=l.academy_id AND a.id=l.account_id WHERE l.academy_id=e.academy_id AND l.journal_id=e.journal_id) contexts CROSS JOIN(VALUES ('counterparty-balances.view'),('financial-reports.view'),('journals.view'),('accounts.view'),('ledger.view')) cap(name) WHERE public.scope_contains($4::jsonb->cap.name,jsonb_build_object('all',contexts.hub_id IS NULL,'hubs',CASE WHEN contexts.hub_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(contexts.hub_id) END)) IS NOT TRUE) allowed
 FROM public.counterparty_balance_events e JOIN public.finance_journals j ON j.academy_id=e.academy_id AND j.id=e.journal_id WHERE e.academy_id=(SELECT academy_id FROM party) AND e.payee_id=$1 AND e.posted_on<=$3::date AND $3::date-$2::date<=3660 AND($10::uuid[] IS NULL OR e.currency_id=ANY($10))
 UNION ALL SELECT b.academy_id,b.id,0,b.posted_on,b.currency_id,b.unit_scale,-b.gross_minor,'payable','bill',NULL::uuid,b.allowed FROM bills b
 UNION ALL SELECT b.academy_id,j.id,0,j.posted_on,b.currency_id,b.unit_scale,b.gross_minor,'payable','bill_void',j.reverses_id,b.allowed FROM bills b JOIN public.finance_journals j ON j.academy_id=b.academy_id AND j.id=b.void_id WHERE j.posted_on<=$3::date
 UNION ALL SELECT b.academy_id,e.journal_id,0,e.posted_on,b.currency_id,b.unit_scale,e.delta_minor,'payable',CASE WHEN p.settlement_kind='collector_offset' THEN 'noncash_offset' ELSE 'recorded_payment' END||CASE WHEN j.reverses_id IS NULL THEN '' ELSE '_correction' END,j.reverses_id,b.allowed FROM bills b JOIN public.expense_payment_events e ON e.academy_id=b.academy_id AND e.bill_id=b.id JOIN public.expense_payments p ON p.academy_id=e.academy_id AND p.id=e.payment_id JOIN public.finance_journals j ON j.academy_id=e.academy_id AND j.id=e.journal_id WHERE e.posted_on<=$3::date
 UNION ALL SELECT e.academy_id,e.journal_id,0,e.posted_on,a.currency_id,u.unit_scale,e.delta_minor,'custody',CASE WHEN p.id IS NOT NULL THEN 'noncash_offset' WHEN m.id IS NOT NULL THEN 'remittance_'||m.direction WHEN r.id IS NOT NULL THEN 'tuition_receipt' ELSE 'unknown' END||CASE WHEN j.reverses_id IS NULL THEN '' ELSE '_correction' END,j.reverses_id,
  NOT EXISTS(SELECT 1 FROM(SELECT c.hub_id UNION SELECT a.hub_id) contexts CROSS JOIN(VALUES ('counterparty-balances.view'),('financial-reports.view'),('accounts.view'),('ledger.view'),('remittances.view')) cap(name) WHERE public.scope_contains($4::jsonb->cap.name,jsonb_build_object('all',contexts.hub_id IS NULL,'hubs',CASE WHEN contexts.hub_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(contexts.hub_id) END)) IS NOT TRUE) AND public.approval_scope_nonempty($4::jsonb->'collectors.view') AND(c.hub_id IS NULL OR public.scope_contains($4::jsonb->'collectors.view',jsonb_build_object('all',c.hub_id IS NULL,'hubs',CASE WHEN c.hub_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(c.hub_id) END)))
 FROM party party JOIN public.finance_collectors c ON c.academy_id=party.academy_id AND((party.kind='hub' AND c.kind='hub' AND c.hub_id=party.hub_id) OR(party.kind='person' AND c.kind='person' AND c.person_id=party.person_id) OR(party.kind='organization' AND c.organization_payee_id=party.id))
 JOIN public.collector_fund_events e ON e.academy_id=c.academy_id AND e.collector_id=c.id JOIN public.finance_accounts a ON a.academy_id=e.academy_id AND a.id=e.holding_account JOIN public.finance_currency_revisions u ON u.academy_id=a.academy_id AND u.currency_id=a.currency_id AND u.version=a.currency_version
 JOIN public.finance_journals j ON j.academy_id=e.academy_id AND j.id=e.journal_id LEFT JOIN public.expense_payments p ON p.academy_id=j.academy_id AND p.id=coalesce(j.reverses_id,j.id) AND p.settlement_kind='collector_offset' LEFT JOIN public.collector_remittances m ON m.academy_id=j.academy_id AND m.id=coalesce(j.reverses_id,j.id) LEFT JOIN public.tuition_receipts r ON r.academy_id=j.academy_id AND r.id=coalesce(j.reverses_id,j.id)
 WHERE e.posted_on<=$3::date AND $3::date-$2::date<=3660 AND($10::uuid[] IS NULL OR a.currency_id=ANY($10))
 LIMIT 200001
),bound AS MATERIALIZED(SELECT count(*)::integer n,count(*) FILTER(WHERE allowed IS NOT TRUE)::integer denied,count(*) FILTER(WHERE category LIKE 'unknown%')::integer unknown FROM raw),
 normalized AS MATERIALIZED(SELECT r.*,max(unit_scale) OVER(PARTITION BY currency_id) scale FROM raw r CROSS JOIN bound b WHERE b.n<=200000 AND b.denied=0 AND(SELECT allowed FROM party_access) AND(SELECT count(*) FROM bills)<=10000),
 amounts AS MATERIALIZED(SELECT *,delta_minor*('1'||repeat('0',scale-unit_scale))::numeric amount FROM normalized),
 ordered AS MATERIALIZED(SELECT *,sum(amount) OVER(PARTITION BY currency_id ORDER BY posted_on,journal_id,family COLLATE "C",line_number ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) balance FROM amounts),
 totals AS(SELECT currency_id,max(scale) scale,coalesce(sum(amount) FILTER(WHERE posted_on<$2::date),0)::text opening,coalesce(sum(greatest(amount,0)) FILTER(WHERE posted_on>=$2::date),0)::text increases,coalesce(sum(greatest(-amount,0)) FILTER(WHERE posted_on>=$2::date),0)::text decreases,sum(amount)::text closing,
 coalesce(sum(amount) FILTER(WHERE family='manual_balance'),0)::text manual_balance,coalesce(sum(amount) FILTER(WHERE family='custody'),0)::text custody,coalesce(sum(amount) FILTER(WHERE family='payable'),0)::text payable FROM amounts GROUP BY currency_id),
 windowed AS MATERIALIZED(SELECT * FROM ordered WHERE posted_on>=$2::date),daily AS MATERIALIZED(SELECT currency_id,posted_on,sum(amount) amount FROM windowed GROUP BY currency_id,posted_on),
 day_balances AS(SELECT d.currency_id,d.posted_on::text AS "postedOn",d.amount::text change,(t.opening::numeric+sum(d.amount) OVER(PARTITION BY d.currency_id ORDER BY d.posted_on))::text balance FROM daily d JOIN totals t ON t.currency_id=d.currency_id),
 page AS(SELECT journal_id AS "journalId",line_number AS "lineNumber",posted_on::text AS "postedOn",currency_id AS "currencyId",family,category,correction_of AS "correctionOfId",amount::text change,balance::text FROM windowed WHERE $5::date IS NULL OR(posted_on,journal_id,family COLLATE "C",line_number)>($5::date,$6::uuid,$7::text COLLATE "C",$8::integer) ORDER BY posted_on,journal_id,family COLLATE "C",line_number LIMIT $9),
contexts AS MATERIALIZED(
 SELECT a.hub_id FROM(SELECT DISTINCT academy_id,journal_id FROM raw) r JOIN public.finance_journal_lines l ON l.academy_id=r.academy_id AND l.journal_id=r.journal_id JOIN public.finance_accounts a ON a.academy_id=l.academy_id AND a.id=l.account_id
 UNION SELECT l.hub_id FROM bills b JOIN public.expense_bill_lines l ON l.academy_id=b.academy_id AND l.bill_id=b.id
 UNION SELECT a.hub_id FROM bills b JOIN public.expense_payments p ON p.academy_id=b.academy_id AND p.bill_id=b.id JOIN public.finance_accounts a ON a.academy_id=p.academy_id AND a.id=p.funding_account
 UNION SELECT c.hub_id FROM(SELECT DISTINCT academy_id,journal_id FROM raw WHERE family='custody') r JOIN public.collector_fund_events e ON e.academy_id=r.academy_id AND e.journal_id=r.journal_id JOIN public.finance_collectors c ON c.academy_id=e.academy_id AND c.id=e.collector_id
 UNION SELECT hub_id FROM party WHERE hub_id IS NOT NULL
),scope AS(SELECT CASE WHEN count(*)=0 OR bool_or(hub_id IS NULL) THEN jsonb_build_object('all',true,'hubs','[]'::jsonb) ELSE jsonb_build_object('all',false,'hubs',jsonb_agg(hub_id ORDER BY hub_id)) END value FROM contexts),
 proof_gate AS(SELECT (SELECT allowed FROM party_access) AND(SELECT n<=200000 AND denied=0 AND unknown=0 FROM bound) AND(SELECT count(*) FROM bills)<=10000 AND(SELECT count(*) FROM totals)<=1000 AND(SELECT count(*) FROM daily)<=10000 AND $3::date-$2::date<=3660 allowed)
SELECT statement_timestamp()::text AS "snapshotAt",(SELECT n FROM bound) AS "sourceCount",(SELECT denied FROM bound)+CASE WHEN(SELECT allowed FROM party_access) THEN 0 ELSE 1 END denied,(SELECT unknown FROM bound) unknown,(SELECT count(*)::integer FROM bills) AS "billCount",(SELECT count(*)::integer FROM totals) AS "currencyCount",(SELECT count(*)::integer FROM daily) AS "dayCount",(SELECT count(*)::integer FROM windowed) AS "entryCount",$3::date-$2::date<=3660 AS "validRange",
 coalesce((SELECT jsonb_agg(to_jsonb(t)||jsonb_build_object('currencyCode',c.code) ORDER BY c.code,t.currency_id) FROM totals t JOIN public.finance_currencies c ON c.id=t.currency_id WHERE(SELECT count(*) FROM totals)<=1000 AND(SELECT count(*) FROM daily)<=10000),'[]'::jsonb) currencies,
 coalesce((SELECT jsonb_agg(to_jsonb(page) ORDER BY "postedOn","journalId",family COLLATE "C","lineNumber") FROM page),'[]'::jsonb) entries,
 coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY "postedOn",currency_id) FROM day_balances d WHERE(SELECT count(*) FROM totals)<=1000 AND(SELECT count(*) FROM daily)<=10000),'[]'::jsonb) days,
 CASE WHEN(SELECT allowed FROM proof_gate) THEN encode(sha256(convert_to(jsonb_build_array('counterparty-statement-source-v1',(SELECT academy_id FROM party),$1::uuid,$2::date,$3::date,(SELECT coalesce(jsonb_agg(id ORDER BY id),'[]'::jsonb) FROM unnest($10::uuid[]) id),(SELECT to_jsonb(p) FROM party p),(SELECT value FROM scope),(SELECT coalesce(string_agg(encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex'),'' ORDER BY posted_on,journal_id,family COLLATE "C",line_number),'') FROM raw r))::text,'UTF8')),'hex') ELSE NULL END AS "sourceFingerprint",
 CASE WHEN(SELECT allowed FROM proof_gate) THEN(SELECT value FROM scope) ELSE NULL END AS "sourceScope";
END $native$;
REVOKE ALL ON FUNCTION public.counterparty_statement_rows(uuid,date,date,jsonb,date,uuid,text,integer,integer,uuid[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.counterparty_statement_rows(uuid,date,date,jsonb,date,uuid,text,integer,integer,uuid[]) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 273 $$;

